  values
    (v_chapter, 'mcq', 'scenario', 'bank', 5, 'A student mixes hydrochloric acid and sodium hydroxide in a beaker. The beaker becomes warm. This observation indicates that the reaction is:', '["Endothermic","Exothermic","Reversible","Photochemical"]'::jsonb, 'B', 1),
